DROP TABLE IF EXISTS `personales_legajos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `personales_legajos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `persona_id` bigint(20) DEFAULT NULL,
  `dni` char(8) DEFAULT NULL,
  `appaterno` varchar(255) DEFAULT NULL,
  `apmaterno` varchar(255) DEFAULT NULL,
  `nombres` varchar(255) DEFAULT NULL,
  `datos` varchar(255) DEFAULT NULL,
  `personal_id` bigint(20) DEFAULT NULL,
  `regimen` varchar(255) DEFAULT NULL,
  `tipo_regimen` varchar(255) DEFAULT NULL,
  `cargo` varchar(255) DEFAULT NULL,
  `cargo_condicion` varchar(255) DEFAULT NULL,
  `codsedeorigen` bigint(20) DEFAULT NULL,
  `sedeorigen` varchar(255) DEFAULT NULL,
  `coddependenciaorigen` bigint(20) DEFAULT NULL,
  `dependenciaorigen` varchar(255) DEFAULT NULL,
  `coddespachoorigen` bigint(20) DEFAULT NULL,
  `despachoorigen` varchar(255) DEFAULT NULL,
  `codsededestino` bigint(20) DEFAULT NULL,
  `sededestino` varchar(255) DEFAULT NULL,
  `coddependenciadestino` bigint(20) DEFAULT NULL,
  `dependenciadestino` varchar(255) DEFAULT NULL,
  `coddespachodestino` bigint(20) DEFAULT NULL,
  `despachodestino` varchar(255) DEFAULT NULL,
  `celpersonal` varchar(255) DEFAULT NULL,
  `correopersonal` varchar(255) DEFAULT NULL,
  `celinstitucional` varchar(255) DEFAULT NULL,
  `correoinstitucional` varchar(255) DEFAULT NULL,
  `tipo_documento` varchar(255) DEFAULT NULL,
  `motivo` varchar(255) DEFAULT NULL,
  `titulodocumento` varchar(255) DEFAULT NULL,
  `fechaemision` date DEFAULT NULL,
  `ruta_legajo` varchar(255) DEFAULT NULL,
  `informatico_dni` char(8) DEFAULT NULL,
  `informatico` varchar(255) DEFAULT NULL,
  `activo` char(1) DEFAULT NULL,
  `created_user` varchar(255) DEFAULT NULL,
  `updated_user` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=128 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
