  `coddespachoorigen` bigint(20) DEFAULT NULL,
  `despachoorigen` varchar(255) DEFAULT NULL,
  `numexpediente` varchar(255) DEFAULT NULL,
  `expdetalle` varchar(255) DEFAULT NULL,
  `estado` char(20) DEFAULT NULL,
  `oficina_ubicacion` varchar(255) DEFAULT NULL,
  `asignado_a` varchar(255) DEFAULT NULL,
  `fecha` date DEFAULT NULL,
  `activo` char(1) DEFAULT NULL,
  `created_user` varchar(255) DEFAULT NULL,
  `updated_user` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
