DROP TABLE IF EXISTS `patrimonios_bienes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `patrimonios_bienes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo_patrimonial` varchar(100) NOT NULL,
  `descripcion` varchar(255) DEFAULT NULL,
  `nombre_sede` varchar(150) DEFAULT NULL,
  `nombre_depend` varchar(150) DEFAULT NULL,
  `responsable_id` bigint(20) DEFAULT NULL,
  `responsable_dni` char(8) DEFAULT NULL,
  `responsable` varchar(150) DEFAULT NULL,
  `usuario_id` bigint(20) DEFAULT NULL,
  `usuario_dni` char(8) DEFAULT NULL,
  `usuario` varchar(150) DEFAULT NULL,
  `nombre_prov` varchar(150) DEFAULT NULL,
  `fecha_compra` date DEFAULT NULL,
  `valor_compra` decimal(12,2) DEFAULT NULL,
  `fecha_alta` date DEFAULT NULL,
  `valor_inicial` decimal(12,2) DEFAULT NULL,
  `sede` varchar(100) DEFAULT NULL,
  `pliego` varchar(100) DEFAULT NULL,
  `ubicac_fisica` varchar(150) DEFAULT NULL,
  `nombre_item` varchar(150) DEFAULT NULL,
  `sec_ejec` varchar(50) DEFAULT NULL,
  `tipo_modalidad` varchar(100) DEFAULT NULL,
  `codigo_barra` varchar(100) DEFAULT NULL,
  `modelo` varchar(100) DEFAULT NULL,
  `nro_orden` varchar(100) DEFAULT NULL,
  `medidas` varchar(100) DEFAULT NULL,
  `hvalor_neto` decimal(12,2) DEFAULT NULL,
  `abrev_movimto` varchar(50) DEFAULT NULL,
  `secuencia` varchar(50) DEFAULT NULL,
  `nro_documento` varchar(100) DEFAULT NULL,
  `flag_compartido` varchar(10) DEFAULT NULL,
  `marca` varchar(100) DEFAULT NULL,
  `centro_costo` varchar(100) DEFAULT NULL,
  `estado` varchar(50) DEFAULT NULL,
  `abreviatura` varchar(50) DEFAULT NULL,
  `fecha_nea` date DEFAULT NULL,
  `tipo_doc_refer` varchar(100) DEFAULT NULL,
  `sec_modelo` varchar(50) DEFAULT NULL,
  `nro_serie` varchar(100) DEFAULT NULL,
  `grupo_bien` varchar(100) DEFAULT NULL,
  `clase_bien` varchar(100) DEFAULT NULL,
  `familia_bien` varchar(100) DEFAULT NULL,
  `item_bien` varchar(100) DEFAULT NULL,
  `color` varchar(50) DEFAULT NULL,
  `caracteristicas` text DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `asignacion` char(50) DEFAULT NULL,
  `ruta_documento` varchar(255) DEFAULT NULL,
  `activo` char(1) DEFAULT NULL,
  `ip` varchar(255) DEFAULT NULL,
  `created_user` varchar(255) DEFAULT NULL,
  `updated_user` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`,`codigo_patrimonial`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10853 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
