--
-- Table structure for table `personales_atenciones`
--

DROP TABLE IF EXISTS `personales_atenciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `personales_atenciones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `persona_id` bigint(20) DEFAULT NULL,
  `dni` char(8) DEFAULT NULL,
  `nombres` varchar(255) DEFAULT NULL,
  `appaterno` varchar(255) DEFAULT NULL,
  `apmaterno` varchar(255) DEFAULT NULL,
  `celpersonal` varchar(255) DEFAULT NULL,
  `celinstitucional` varchar(255) DEFAULT NULL,
  `correopersonal` varchar(255) DEFAULT NULL,
  `correoinstitucional` varchar(255) DEFAULT NULL,
  `datos` varchar(255) DEFAULT NULL,
  `personal_id` bigint(20) DEFAULT NULL,
  `codsedeorigen` bigint(20) DEFAULT NULL,
  `sedeorigen` varchar(255) DEFAULT NULL,
  `coddependenciaorigen` bigint(20) DEFAULT NULL,
  `dependenciaorigen` varchar(255) DEFAULT NULL,
  `coddespachoorigen` bigint(20) DEFAULT NULL,
  `despachoorigen` varchar(255) DEFAULT NULL,
  `codsededestino` bigint(20) DEFAULT NULL,
  `sededestino` varchar(255) DEFAULT NULL,
  `coddependenciadestino` bigint(20) DEFAULT NULL,
  `dependenciadestino` varchar(255) DEFAULT NULL,
  `coddespachodestino` bigint(20) DEFAULT NULL,
  `despachodestino` varchar(255) DEFAULT NULL,
  `regimen` varchar(255) DEFAULT NULL,
  `tipo_regimen` varchar(255) DEFAULT NULL,
  `cargo` varchar(255) DEFAULT NULL,
  `cargo_condicion` varchar(255) DEFAULT NULL,
  `reportado_por` varchar(255) DEFAULT NULL,
  `solicitud_incidencia` varchar(255) DEFAULT NULL,
  `servicio` varchar(255) DEFAULT NULL,
  `detalle_servicio` varchar(255) DEFAULT NULL,
  `bien_id` bigint(20) DEFAULT NULL,
  `cod` varchar(255) DEFAULT NULL,
  `cod_patrimonial` varchar(255) DEFAULT NULL,
  `datos_bien` varchar(255) DEFAULT NULL,
  `ip` varchar(255) DEFAULT NULL,
  `cea` varchar(255) DEFAULT NULL,
  `sgf` varchar(255) DEFAULT NULL,
  `glpi` varchar(255) DEFAULT NULL,
  `enviado_lima` char(2) DEFAULT NULL,
  `detalle_problema` text DEFAULT NULL,
  `ncopias` int(11) DEFAULT NULL,
  `obs_usuario` text DEFAULT NULL,
  `obs_informatico` text DEFAULT NULL,
  `estado` char(20) DEFAULT NULL,
  `atendido` char(2) DEFAULT NULL,
  `atendido_por_id` int(11) DEFAULT NULL,
  `atendido_por_dni` varchar(255) DEFAULT NULL,
  `atendido_por_datos` varchar(255) DEFAULT NULL,
  `tiempo_atencion` varchar(255) DEFAULT NULL,
  `respuesta` text DEFAULT NULL,
  `conformidad` char(1) DEFAULT NULL,
  `ruta_evidencia` varchar(255) DEFAULT NULL,
  `ruta_documento` varchar(255) DEFAULT NULL,
  `informatico_dni` char(8) DEFAULT NULL,
  `informatico` varchar(255) DEFAULT NULL,
  `activo` char(1) DEFAULT NULL,
  `created_user_cargo` varchar(255) DEFAULT NULL,
  `created_user` varchar(255) DEFAULT NULL,
  `updated_user` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5400 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

