-- Table structure for table `informaticas_ips`
--

DROP TABLE IF EXISTS `informaticas_ips`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `informaticas_ips` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `red` varchar(255) DEFAULT NULL,
  `grupo` varchar(15) DEFAULT NULL,
  `ip` varchar(15) NOT NULL,
  `bien_id` bigint(20) DEFAULT NULL,
  `codigo` varchar(255) DEFAULT NULL,
  `codigo_patrimonial` varchar(255) DEFAULT NULL,
  `bien` varchar(255) DEFAULT NULL,
  `estado` varchar(255) DEFAULT NULL,
  `persona_id` bigint(20) DEFAULT NULL,
  `dni` varchar(8) DEFAULT NULL,
  `nombres` varchar(255) DEFAULT NULL,
  `apppaterno` varchar(255) DEFAULT NULL,
  `apmaterno` varchar(255) DEFAULT NULL,
  `sede` varchar(255) DEFAULT NULL,
  `dependencia` varchar(255) DEFAULT NULL,
  `despacho` varchar(255) DEFAULT NULL,
  `regimen` varchar(255) DEFAULT NULL,
  `tipo` varchar(255) DEFAULT NULL,
  `cargo` varchar(255) DEFAULT NULL,
  `condicion` varchar(255) DEFAULT NULL,
  `activo` char(1) DEFAULT NULL,
  `created_user` varchar(255) DEFAULT NULL,
  `updated_user` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`,`ip`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4972 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

